import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as o,a as r,b as l}from"./chunks/M-S-SW3e.XAlFcJrn.js";import{_ as s,o as i,c as n,a3 as b}from"./chunks/framework.g9mfNVRQ.js";const y=JSON.parse('{"title":"Pebble","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/pebble.md","filePath":"smartwatch/pebble.md"}'),p={name:"smartwatch/pebble.md"};function d(c,e,m,h,_,w){return i(),n("div",null,[...e[0]||(e[0]=[b('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Smart Watch Features<br>   Pebble integration</p></div><p>xDrip supports both the original Pebble watches (discontinued in 2016) and the new Pebble models relaunched in 2025 (Pebble 2 Duo, Pebble Time 2).</p><p>After you&#39;ve paired your Pebble with your phone, you can enable it in xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Pebble watch integration <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>xDrip will then install the watchface itself (no need to download it).</p><img src="'+o+'" style="zoom:75%;"><p>It will also offer to install the snooze button app, if you skipped it you can do it later with Install Pebble Apps at the bottom.</p><img src="'+r+'" style="zoom:75%;"><p>You can select different watchfaces.</p><div class="admonition xdripitem"><p class="admonition-title">Choose Pebble watchface</p></div><img src="'+l+'" style="zoom:75%;"><h2 id="new-pebble-models-2025-onwards" tabindex="-1">New Pebble models (2025 onwards) <a class="header-anchor" href="#new-pebble-models-2025-onwards" aria-label="Permalink to &quot;New Pebble models (2025 onwards)&quot;">​</a></h2><p>Select the Pebble Trend Clay Version (All Models) watchface (<a href="https://github.com/jstevensog/xDrip-Pebble-E" target="_blank" rel="noreferrer">xDrip-Pebble-E</a>). It works on all Pebble models, old and new, with full color on color watches including the new Pebble Time 2.</p><h2 id="legacy-pebble-models" tabindex="-1">Legacy Pebble models <a class="header-anchor" href="#legacy-pebble-models" aria-label="Permalink to &quot;Legacy Pebble models&quot;">​</a></h2><p>With recent Android versions, using a legacy Pebble watch is <a href="https://www.reddit.com/r/pebble/comments/1776bbx/installing_pebble_apk_on_fresh_android_14_setup/" target="_blank" rel="noreferrer">challenging</a>. Use <a href="https://rebble.io/" target="_blank" rel="noreferrer">Rebble</a> resources.</p><p>The Standard, Color Trend and Pebble Classic Trend watchfaces were made for the original Pebble models. The Pebble Trend Clay Version (All Models) watchface works on legacy models too.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.08.08" target="_blank" rel="noreferrer"><em>Last modified 8/8/2026</em></a></p>',18)])])}const x=s(p,[["render",d]]);export{y as __pageData,x as default};
